<script>
(function(){const form=document.getElementById('lessonLeadForm');if(!form)return;const preferredDate=form.elements.data_preferida,preferredHour=form.elements.hora_preferida;if(preferredDate&&preferredHour){const now=new Date(),pad=value=>String(value).padStart(2,'0');preferredDate.min=`${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;const updateHours=()=>{preferredHour.innerHTML='';const selected=preferredDate.value?new Date(`${preferredDate.value}T12:00:00`):null,day=selected?selected.getDay():-1,hours=day>=1&&day<=5?[18,19,20,21]:day===6?[8,9,10,11,12]:[];if(!hours.length){preferredHour.innerHTML=`<option value="">${day===0?'Domingo indisponível':'Escolha uma data disponível'}</option>`;preferredHour.disabled=true;preferredDate.setCustomValidity(day===0?'Domingo não possui horários disponíveis.':'');return}preferredDate.setCustomValidity('');preferredHour.innerHTML='<option value="">Selecione</option>'+hours.map(hour=>`<option value="${pad(hour)}">${hour}h</option>`).join('');preferredHour.disabled=false};preferredDate.addEventListener('change',updateHours);updateHours()}document.querySelectorAll('[data-interest]').forEach(link=>link.addEventListener('click',()=>{const select=form.elements.interesse;if(select)select.value=link.dataset.interest||'';}));const attribution=typeof window.techSantosAttribution==='function'?window.techSantosAttribution():{};const map={campaign_source:'utm_source',campaign_medium:'utm_medium',campaign_name:'utm_campaign',campaign_content:'utm_content',campaign_term:'utm_term',campaign_landing_page:'landing_page'};Object.entries(map).forEach(([key,name])=>{if(form.elements[name]&&attribution[key])form.elements[name].value=attribution[key]});if(form.elements.landing_page&&!form.elements.landing_page.value)form.elements.landing_page.value=location.pathname;form.addEventListener('submit',async event=>{if(!form.reportValidity())return;event.preventDefault();const button=form.querySelector('button[type="submit"]');const message=document.getElementById('lessonMessage');button.disabled=true;button.textContent='Enviando objetivo...';message.className='lesson-message';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.message||'Não foi possível enviar.');message.textContent=result.message;message.className='lesson-message show ok';form.reset();if(typeof window.techSantosTrack==='function')window.techSantosTrack('generate_lead',{lead_type:'aula_particular',form_name:'solicitar_horario'},'Lead',true)}catch(error){message.textContent=error.message||'Não foi possível enviar. Fale conosco pelo WhatsApp.';message.className='lesson-message show error'}finally{button.disabled=false;button.textContent='Enviar objetivo e solicitar horário';message.scrollIntoView({behavior:'smooth',block:'nearest'})}})})();
</script>
</body></html>
